CREATE OR REPLACE FUNCTION public.guard_plan_tools() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT has_role(auth.uid(),'admin') AND ((TG_OP='INSERT' AND NEW.includes_reservations_sales_tools) OR (TG_OP='UPDATE' AND NEW.includes_reservations_sales_tools IS DISTINCT FROM OLD.includes_reservations_sales_tools)) THEN RAISE EXCEPTION 'Only admin can change reservations and sales tools inclusion'; END IF; RETURN NEW; END $$; CREATE TRIGGER guard_plan_tools_insert BEFORE INSERT ON public.plan_versions FOR EACH ROW EXECUTE FUNCTION public.guard_plan_tools(); CREATE TRIGGER guard_custom_tools_insert BEFORE INSERT ON public.custom_plans FOR EACH ROW EXECUTE FUNCTION public.guard_plan_tools();
CREATE OR REPLACE FUNCTION public.enforce_task_evidence() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='done' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'done') AND EXISTS(SELECT 1 FROM checklist_templates t WHERE t.id=NEW.template_id AND t.gate_code='gate_d' AND t.evidence_required) AND coalesce(trim(NEW.evidence_url),'')='' THEN RAISE EXCEPTION 'Gate D task needs an evidence link or uploaded file before it can be marked Done'; END IF; RETURN NEW; END $$; CREATE TRIGGER a_gate_d_insert_evidence BEFORE INSERT ON public.client_tasks FOR EACH ROW EXECUTE FUNCTION public.enforce_task_evidence();
CREATE FUNCTION public.guard_approved_influencer_contract() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.status='approved' AND (NEW.status<>'approved' OR NEW.contract_url IS DISTINCT FROM OLD.contract_url OR NEW.approved_by IS DISTINCT FROM OLD.approved_by OR NEW.approved_at IS DISTINCT FROM OLD.approved_at) THEN RAISE EXCEPTION 'Approved contract is preserved; create a new launch program for a new contract'; END IF; RETURN NEW; END $$; CREATE TRIGGER guard_approved_influencer_contract BEFORE UPDATE ON public.influencer_programs FOR EACH ROW EXECUTE FUNCTION public.guard_approved_influencer_contract();